"TETON\",\"to\":\"TROPICAL_BIRDS\",\"meters\":651.192185626034,\"accessFactor\":1,\"accessPenaltyMeters\":651.192185626034,\"accessBasis\":\"GPS_BASELINE\"},{\"from\":\"TETON\",\"to\":\"WEST_ADMIN\",\"meters\":529.6270044396,\"accessFactor\":1,\"accessPenaltyMeters\":529.6270044396,\"accessBasis\":\"GPS_BASELINE\"},{\"from\":\"TETON\",\"to\":\"ZAMBEZI\",\"meters\":371.3934522745182,\"accessFactor\":1,\"accessPenaltyMeters\":371.3934522745182,\"accessBasis\":\"GPS_BASELINE\"},{\"from\":\"TROPICAL_BIRDS\",\"to\":\"WEST_ADMIN\",\"meters\":134.3538929845857,\"accessFactor\":1,\"accessPenaltyMeters\":134.3538929845857,\"accessBasis\":\"GPS_BASELINE\"},{\"from\":\"TROPICAL_BIRDS\",\"to\":\"ZAMBEZI\",\"meters\":280.78673609909043,\"accessFactor\":1,\"accessPenaltyMeters\":280.78673609909043,\"accessBasis\":\"GPS_BASELINE\"},{\"from\":\"WEST_ADMIN\",\"to\":\"ZAMBEZI\",\"meters\":159.75465170947604,\"accessFactor\":1,\"accessPenaltyMeters\":159.75465170947604,\"accessBasis\":\"GPS_BASELINE\"}],\"fixedDenominatorMeters\":807.6262463035904,\"directConnectionFactor\":0.8,\"sharedNeighborhoodFactor\":0.9,\"otherFactor\":1,\"overlapsStacked\":false,\"transitiveNeighborhoodMerging\":false,\"acceptedLongRoute\":[\"ZAMBEZI\",\"TROPICAL_BIRDS\"],\"acceptedLongRouteDiscounted\":false,\"formulaApproved\":true,\"approvalQuestionId\":\"call_97aaa12c08a84a0e8afed222696e481c\",\"walkingTimeClaimed\":false,\"walkingDistancesMeasured\":false,\"productionWritten\":false,\"accessProposalDigest\":\"d4100dc85c5b031a537875b0cd84abada922c8bfb16ac510130ac6467750275b\"}}$corrected_manual_policy$::jsonb else null end;\n if policy is null or policy->>'manualDataDigest' is distinct from source#>>'{version,lunchCoveragePolicy,sourceDigest}'\n then raise exception 'Exact admitted manual absence policy required';end if;"
      }
    ],
    "beforeSha256": "dbf91ab9acba1778c4cfdeed62f2863ab26fe2f98b1452cef6d95f0ce1b25e46",
    "afterSha256": "05707c3f4aa5772375b9be55008df9e48d149eaea7d92ef45d1e65119447d280",
    "inventoryFunction": false,
    "inventoryGrant": false,
    "grantIdentity": "public.static_weekly_manual_assert_recurring_projection(uuid,uuid,jsonb,jsonb)"
  },
  {
    "identity": "public.custodial_release_canary_authority_surface()",
    "replacements": [
      {
        "old": "  values\n",
        "new": "  values\n    ('function','public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n    ('function','public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)','exact approved manual shift policy and component count authority'),\n    ('function','public.static_weekly_manual_period_basis(uuid,uuid,date,bigint,uuid)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_manual_period_basis(uuid,uuid,date,bigint,uuid)','exact approved manual shift policy and component count authority'),\n    ('function','public.static_weekly_manual_assert_native_projection(uuid,uuid,jsonb)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_manual_assert_native_projection(uuid,uuid,jsonb)','exact approved manual shift policy and component count authority'),\n    ('function','public.static_weekly_manual_assert_initial_employment_projection(uuid,uuid,jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_manual_assert_initial_employment_projection(uuid,uuid,jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n    ('function','public.static_weekly_manual_assert_recurring_projection(uuid,uuid,jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n    ('grant','public.static_weekly_manual_assert_recurring_projection(uuid,uuid,jsonb,jsonb)','exact approved manual shift policy and component count authority'),\n"
      }
    ],
    "beforeSha256": "604eb3727f6df05b1f9a98e9d584a97696998d93419c734b2608ea12f6c93319",
    "afterSha256": "bb16474f41949f5808f93784d9b758477433ddcf08ba80b9171bc4a63d26e846",
    "inventoryFunction": true,
    "inventoryGrant": true,
    "grantIdentity": "custodial_release_canary_authority_surface()"
  }
]$count_changes$::jsonb) LOOP
  target:=to_regprocedure(item->>'identity');
  IF target IS NULL THEN RAISE EXCEPTION 'Exact manual count predecessor missing: %',item->>'identity';END IF;
  original:=pg_get_functiondef(target);
  IF public.static_weekly_digest_text(original) IS DISTINCT FROM item->>'beforeSha256'
  THEN RAISE EXCEPTION 'Exact manual count predecessor changed: %',item->>'identity';END IF;
  SELECT proowner,proacl,prosecdef,proconfig INTO STRICT before_owner,before_acl,before_security,before_config FROM pg_proc WHERE oid=target;
  before_grants:=public.custodial_release_authority_current_grant_definition(item->>'grantIdentity');
  IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory WHERE
    CASE WHEN object_kind='function' THEN to_regprocedure(object_identity) END=target)<>(item->>'inventoryFunction')::boolean::integer
   OR (SELECT count(*) FROM public.custodial_release_authority_restore_inventory WHERE
    CASE WHEN object_kind='grant' AND position('(' IN object_identity)>0 THEN to_regprocedure(object_identity) END=target)<>(item->>'inventoryGrant')::boolean::integer
   OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE
    CASE WHEN object_kind='function' THEN to_regprocedure(object_identity) END=target AND (definition_sql IS DISTINCT FROM original OR definition_sha256 IS DISTINCT FROM item->>'beforeSha256'))
   OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE
    CASE WHEN object_kind='grant' AND position('(' IN object_identity)>0 THEN to_regprocedure(object_identity) END=target AND (definition_sql IS DISTINCT FROM before_grants OR definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(before_grants)))
   OR (SELECT count(*) FROM manual_shift_count_roots_before WHERE
    CASE WHEN object_kind='function' THEN to_regprocedure(object_identity) END=target)<>(item->>'inventoryFunction')::boolean::integer
   OR (SELECT count(*) FROM manual_shift_count_roots_before WHERE
    CASE WHEN object_kind='grant' AND position('(' IN object_identity)>0 THEN to_regprocedure(object_identity) END=target)<>(item->>'inventoryGrant')::boolean::integer
  THEN RAISE EXCEPTION 'Exact manual shift predecessor recovery/root membership differs: %',item->>'identity';END IF;
  changed:=original;
  FOR edit IN SELECT value FROM jsonb_array_elements(item->'replacements') LOOP
   IF length(changed)-length(replace(changed,edit->>'old',''))<>length(edit->>'old')
   THEN RAISE EXCEPTION 'Manual count seam missing or repeated';END IF;
   changed:=replace(changed,edit->>'old',edit->>'new');
  END LOOP;
  inverse:=changed;
  FOR edit IN SELECT value FROM jsonb_array_elements(item->'replacements') WITH ORDINALITY x(value,n) ORDER BY n DESC LOOP
   IF length(inverse)-length(replace(inverse,edit->>'new',''))<>length(edit->>'new')
   THEN RAISE EXCEPTION 'Manual count inverse seam differs';END IF;
   inverse:=replace(inverse,edit->>'new',edit->>'old');
  END LOOP;
  IF inverse IS DISTINCT FROM original OR public.static_weekly_digest_text(changed) IS DISTINCT FROM item->>'afterSha256'
  THEN RAISE EXCEPTION 'Manual count full inverse/postimage differs';END IF;
  EXECUTE changed;
  IF pg_get_functiondef(target) IS DISTINCT FROM changed
   OR (SELECT proowner FROM pg_proc WHERE oid=target) IS DISTINCT FROM before_owner
   OR (SELECT proacl FROM pg_proc WHERE oid=target) IS DISTINCT FROM before_acl
   OR (SELECT prosecdef FROM pg_proc WHERE oid=target) IS DISTINCT FROM before_security
   OR (SELECT proconfig FROM pg_proc WHERE oid=target) IS DISTINCT FROM before_config
   OR public.custodial_release_authority_current_grant_definition(item->>'grantIdentity') IS DISTINCT FROM before_grants
  THEN RAISE EXCEPTION 'Manual count owner/ACL/security/postimage changed';END IF;
  INSERT INTO manual_shift_count_targets VALUES(item->>'identity',item->>'beforeSha256',item->>'afterSha256',changed,
   (item->>'inventoryFunction')::boolean,(item->>'inventoryGrant')::boolean);
 END LOOP;
END $manual_shift_count$;
ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $manual_shift_count_rebind$
DECLARE item record;affected integer;definition text;kind text;bucket integer;
BEGIN
 FOR item IN SELECT * FROM manual_shift_count_targets ORDER BY identity LOOP
  IF item.inventory_function THEN
   UPDATE public.custodial_release_authority_restore_inventory SET definition_sql=item.definition,
    definition_sha256=item.after_sha,captured_at=statement_timestamp()
   WHERE CASE WHEN object_kind='function' THEN to_regprocedure(object_identity) END=item.identity::regprocedure;
   GET DIAGNOSTICS affected=row_count;
   IF affected<>1 THEN RAISE EXCEPTION 'Exact manual shift recovery function missing';END IF;
  END IF;
  FOREACH kind IN ARRAY ARRAY['function','grant'] LOOP
   IF (kind='function' AND item.inventory_function) OR (kind='grant' AND item.inventory_grant) THEN CONTINUE;END IF;
   definition:=CASE kind WHEN 'function' THEN item.definition
    ELSE public.custodial_release_authority_current_grant_definition(item.identity) END;
   bucket:=CASE kind WHEN 'function' THEN 100000 ELSE 900000 END;
   INSERT INTO public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
   SELECT (SELECT min(n) FROM generate_series(bucket+1,bucket+99998)n WHERE NOT EXISTS(
    SELECT 1 FROM public.custodial_release_authority_restore_inventory i WHERE i.restore_order=n)),kind,item.identity,
    definition,public.static_weekly_digest_text(definition);
  END LOOP;
 END LOOP;
END $manual_shift_count_rebind$;
ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $manual_shift_count_recovery_preserved$
DECLARE row_before record;row_after record;item record;target oid;definition text;
BEGIN
 IF (SELECT count(*) FROM manual_shift_count_targets)<>8
  OR (SELECT count(*) FROM manual_shift_count_targets WHERE inventory_function)<>2
  OR (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>
   (SELECT count(*)+12 FROM manual_shift_count_inventory_before)
  OR (SELECT tgenabled FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable') IS DISTINCT FROM 'A'
 THEN RAISE EXCEPTION 'Exact manual shift recovery counts/ALWAYS guard differ';END IF;
 FOR row_before IN SELECT * FROM manual_shift_count_inventory_before LOOP
  SELECT * INTO STRICT row_after FROM public.custodial_release_authority_restore_inventory WHERE inventory_id=row_before.inventory_id;
  IF (CASE WHEN row_before.object_kind='function' THEN EXISTS(SELECT 1 FROM manual_shift_count_targets
   WHERE inventory_function AND to_regprocedure(row_before.object_identity)=identity::regprocedure) ELSE false END) THEN
   SELECT * INTO STRICT item FROM manual_shift_count_targets WHERE to_regprocedure(row_before.object_identity)=identity::regprocedure;
   IF row_after.definition_sql IS DISTINCT FROM item.definition OR row_after.definition_sha256 IS DISTINCT FROM item.after_sha
    OR (to_jsonb(row_after)-ARRAY['definition_sql','definition_sha256','captured_at']) IS DISTINCT FROM
     (to_jsonb(row_before)-ARRAY['definition_sql','definition_sha256','captured_at'])
   THEN RAISE EXCEPTION 'Manual shift changed unrelated fields on existing recovery function';END IF;
  ELSIF to_jsonb(row_after) IS DISTINCT FROM to_jsonb(row_before) THEN
   RAISE EXCEPTION 'Manual shift changed an unrelated recovery row';
  END IF;
 END LOOP;
 FOR item IN SELECT * FROM manual_shift_count_targets LOOP
  target:=item.identity::regprocedure;
  IF pg_get_functiondef(target) IS DISTINCT FROM item.definition THEN RAISE EXCEPTION 'Manual shift postimage changed after binding';END IF;
  IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory WHERE
   CASE WHEN object_kind='function' THEN to_regprocedure(object_identity) END=target AND definition_sql=item.definition AND definition_sha256=item.after_sha)<>1
  THEN RAISE EXCEPTION 'Manual shift function recovery binding differs';END IF;
  SELECT public.custodial_release_authority_current_grant_definition(object_identity) INTO STRICT definition
   FROM public.custodial_release_authority_restore_inventory WHERE object_kind='grant' AND position('(' IN object_identity)>0
    AND to_regprocedure(object_identity)=target;
  IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory WHERE
   CASE WHEN object_kind='grant' AND position('(' IN object_identity)>0 THEN to_regprocedure(object_identity) END=target AND definition_sql=definition AND definition_sha256=public.static_weekly_digest_text(definition))<>1
  THEN RAISE EXCEPTION 'Manual shift exact existing ACL recovery binding differs';END IF;
 END LOOP;
 IF EXISTS(SELECT * FROM manual_shift_count_roots_before EXCEPT SELECT * FROM public.custodial_release_canary_authority_surface())
  OR EXISTS(SELECT * FROM manual_shift_count_new_roots EXCEPT SELECT * FROM public.custodial_release_canary_authority_surface())
  OR EXISTS(SELECT * FROM public.custodial_release_canary_authority_surface() EXCEPT
   (SELECT * FROM manual_shift_count_roots_before UNION ALL SELECT * FROM manual_shift_count_new_roots))
  OR (SELECT count(*) FROM public.custodial_release_canary_authority_surface())<>(SELECT count(*)+12 FROM manual_shift_count_roots_before)
 THEN RAISE EXCEPTION 'Manual shift changed unrelated canary roots';END IF;
END $manual_shift_count_recovery_preserved$;
COMMIT;
